# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÇOK ADIMLI PROBLEMLERDE TEMSİL SEÇİMİ VE STRATEJİ DEĞİŞTİRME</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Temsil ve Dönüşüm</text>\n  <text x="125" y="100" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Paydası 2, 4, 5, 10, 20, 25, 50</text>\n  <text x="125" y="118" text-anchor="middle" font-size="11.5" fill="#1e3a8a">olan kesirler ➔ Ondalık / Yüzde</text>\n  <text x="125" y="144" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Paydası 3, 6, 7, 9, 12 olan</text>\n  <text x="125" y="162" text-anchor="middle" font-size="11.5" fill="#1e3a8a">işlemler ➔ Kesir ve Şerit Modeli</text>\n  <text x="125" y="196" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">En uygun ortak dil seçilir!</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Kalanın Kesri Modeli</text>\n  <rect x="265" y="92" width="170" height="26" fill="#dcfce7" stroke="#16a34a"/>\n  <line x1="299" y1="92" x2="299" y2="118" stroke="#16a34a"/>\n  <line x1="333" y1="92" x2="333" y2="118" stroke="#16a34a"/>\n  <line x1="367" y1="92" x2="367" y2="118" stroke="#16a34a"/>\n  <line x1="401" y1="92" x2="401" y2="118" stroke="#16a34a"/>\n  <text x="350" y="140" text-anchor="middle" font-size="11" fill="#14532d">• Önce beşte ikisi (2 kutu) gider.</text>\n  <text x="350" y="160" text-anchor="middle" font-size="11" fill="#14532d">• Kalan 3 kutunun üçte ikisi (2 kutu)</text>\n  <text x="350" y="178" text-anchor="middle" font-size="11" fill="#14532d">daha giderse geriye 1 kutu (%20) kalır.</text>\n  <text x="350" y="206" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">1 kutu = 45 TL ➔ Tamamı = 225 TL</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Kısa Yol ve Kontrol</text>\n  <text x="575" y="100" text-anchor="middle" font-size="11" fill="#713f12">• %35\'i harcanan paranın</text>\n  <text x="575" y="118" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">doğrudan %65\'i kalır.</text>\n  <text x="575" y="144" text-anchor="middle" font-size="11" fill="#713f12">• Sonuç tahminiyle virgül</text>\n  <text x="575" y="162" text-anchor="middle" font-size="11" fill="#713f12">hataları hemen fark edilir.</text>\n  <text x="575" y="196" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">Ters işlemle sağlama yapılır!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FİNANSAL OKURYAZARLIK, KARIŞIM VE TASARRUF PROBLEMLERİ</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Birim Fiyat ve Kampanya Karşılaştırması</text>\n  <text x="180" y="100" text-anchor="middle" font-size="11.5" fill="#155e75">• A Marketi: 2,5 kg deterjan = 150 TL</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0e7490">➔ 1 kg Birim Fiyatı: 150 ÷ 2,5 = 60 TL</text>\n  <text x="180" y="148" text-anchor="middle" font-size="11.5" fill="#155e75">• B Marketi: 4 kg deterjan = 260 TL (%10 indirimli)</text>\n  <text x="180" y="168" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0e7490">➔ İndirimli: 234 TL · 1 kg: 234 ÷ 4 = 58,5 TL</text>\n  <text x="180" y="200" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">Karar: B Marketi kg başına 1,5 TL daha ekonomiktir.</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Sürdürülebilirlik ve Tasarruf Hesapları</text>\n  <text x="520" y="100" text-anchor="middle" font-size="11.5" fill="#581c87">• Damlayan musluk günde 12,5 L su harcar.</text>\n  <text x="520" y="122" text-anchor="middle" font-size="11.5" fill="#581c87">• 30 günde: 30 × 12,5 = 375 L su israfı önlenir.</text>\n  <text x="520" y="150" text-anchor="middle" font-size="11.5" fill="#581c87">• Enerji tasarruflu ampul faturayı %20 azaltır:</text>\n  <text x="520" y="170" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">450 TL fatura ➔ 450 × 0,80 = 360 TL\'ye düşer.</text>\n  <text x="520" y="200" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Matematiksel modeller bilinçli tüketimi destekler.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">2. TEMA GENEL DEĞERLENDİRMESİ: SAYILAR VE NİCELİKLER (2)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Kesirlerle İşlemler</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11" fill="#881337">• Toplama-Çıkarma: Payda eşitle</text>\n  <text x="125" y="120" text-anchor="middle" font-size="11" fill="#881337">• Çarpma: Pay×Pay / Payda×Payda</text>\n  <text x="125" y="142" text-anchor="middle" font-size="11" fill="#881337">• Bölme: İkinci kesri ters çevir çarp</text>\n  <text x="125" y="168" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">• 1\'den küçük kesirle çarpmak sayıyı</text>\n  <text x="125" y="186" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">küçültür; bölmek ise büyütür!</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Ondalık Gösterimler</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11" fill="#7c2d12">• Çözümleme: Onluk, Birlik, Onda bir...</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11" fill="#7c2d12">• Yuvarlama: Sağdaki rakama bak (≥5)</text>\n  <text x="350" y="142" text-anchor="middle" font-size="11" fill="#7c2d12">• Çarpma: Toplam basamak kadar virgül</text>\n  <text x="350" y="164" text-anchor="middle" font-size="11" fill="#7c2d12">• Bölme: Böleni doğal sayı yapacak</text>\n  <text x="350" y="182" text-anchor="middle" font-size="11" font-weight="bold" fill="#c2410c">şekilde 10, 100 ile genişlet!</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Yüzdeler ve Problemler</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11" fill="#14532d">• Çokluğun yüzdesini bulma</text>\n  <text x="575" y="120" text-anchor="middle" font-size="11" fill="#14532d">• Yüzdesi verilen bütünü bulma</text>\n  <text x="575" y="142" text-anchor="middle" font-size="11" fill="#14532d">• Bir sayıyı diğerinin yüzdesi yazma</text>\n  <text x="575" y="168" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">• Strateji geliştirme, genelleme</text>\n  <text x="575" y="186" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">ve özgün problem kurma!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
